//! Asserts the rules against `CodeNarc`'s own fixtures.
//!
//! `fixtures/codenarc` is generated by `benchmarks/harvest_codenarc_fixtures.py`
//! from `CodeNarc`'s `*RuleTest.groovy` files: every snippet `CodeNarc` asserts on,
//! with the line numbers it expects. Running them here is what turns "the rule is
//! registered" into "the rule behaves like `CodeNarc` on `CodeNarc`'s own edge cases".
//!
//! A case that does not match yet belongs in `fixtures/codenarc/known-differences.tsv`
//! together with a reason. Entries that start matching must be deleted, so the file
//! cannot quietly hide progress or rot.

use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use groovylint_core::SourceFile;
use groovylint_rules::{Engine, RuleProperties, RuleRegistry};
use groovylint_syntax::parser::parse;

/// What a case expects from the rule under test.
enum Expected {
    /// `assertNoViolations`.
    None,
    /// `assertSingleViolation` without a line number.
    AnyLine,
    /// The exact set of lines that must hold a violation.
    Lines(BTreeSet<usize>),
}

struct Case {
    rule: String,
    /// Path of the fixture, relative to the corpus root.
    key: String,
    /// The source path a path-sensitive rule should see.
    source_path: Option<String>,
    expected: Expected,
    properties: RuleProperties,
}

/// Runs one case and describes the mismatch when it does not match.
fn run(registry: &RuleRegistry, class: &str, case: &Case, path: &Path) -> Result<(), String> {
    let text = std::fs::read_to_string(path).map_err(|error| format!("unreadable: {error}"))?;
    let parsed = parse(&text).map_err(|error| format!("our parser rejected it: {error}"))?;

    let name = case.source_path.clone().unwrap_or_else(|| {
        case.key
            .rsplit('/')
            .next()
            .unwrap_or("Fixture.groovy")
            .to_string()
    });
    let source = SourceFile::new(name, text.as_str());

    let entries = [(class.to_string(), case.properties.clone())];
    let engine = Engine::from_codenarc_entries(registry, &entries);
    if !engine.unsupported().is_empty() {
        return Err("the rule is not registered".to_string());
    }

    let diagnostics = engine.lint(&source, &parsed);
    let lines: BTreeSet<usize> = diagnostics
        .iter()
        .map(|diagnostic| source.line_col(diagnostic.span.start).line)
        .collect();

    let matched = match &case.expected {
        Expected::None => diagnostics.is_empty(),
        Expected::AnyLine => diagnostics.len() == 1,
        Expected::Lines(expected) => &lines == expected,
    };
    if matched {
        return Ok(());
    }

    let expected = match &case.expected {
        Expected::None => "no violations".to_string(),
        Expected::AnyLine => "exactly one violation".to_string(),
        Expected::Lines(expected) => format!("{expected:?}"),
    };
    let messages: Vec<&str> = diagnostics
        .iter()
        .map(|diagnostic| diagnostic.message.as_str())
        .collect();
    Err(format!(
        "expected {expected}, got lines {lines:?} {messages:?}"
    ))
}

fn corpus() -> PathBuf {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/codenarc");
    path.canonicalize()
        .expect("fixtures/codenarc is missing; run benchmarks/harvest_codenarc_fixtures.py")
}

fn parse_expected(field: &str) -> Expected {
    if field == "-" {
        return Expected::None;
    }
    if field.is_empty() {
        return Expected::AnyLine;
    }
    let mut lines = BTreeSet::new();
    for part in field.split(',').filter(|part| !part.is_empty()) {
        let line = part.parse().expect("expected line number");
        lines.insert(line);
    }
    Expected::Lines(lines)
}

fn parse_properties(field: &str) -> RuleProperties {
    let mut properties = RuleProperties::new();
    // Values may themselves contain commas, so the harvester separates pairs with
    // U+001F instead.
    for pair in field.split('\u{1f}').filter(|part| !part.is_empty()) {
        if let Some((key, value)) = pair.split_once('=') {
            properties.insert(key.to_string(), value.to_string());
        }
    }
    properties
}

fn cases(root: &Path) -> Vec<Case> {
    let text = std::fs::read_to_string(root.join("expectations.tsv")).expect("expectations.tsv");
    let mut cases = Vec::new();
    for line in text.lines().filter(|line| !line.trim().is_empty()) {
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 5, "malformed row: {line}");
        cases.push(Case {
            rule: fields[0].to_string(),
            key: fields[1].to_string(),
            source_path: (!fields[2].is_empty()).then(|| fields[2].to_string()),
            expected: parse_expected(fields[3]),
            properties: parse_properties(fields[4]),
        });
    }
    cases
}

/// Keys in `known-differences.tsv`: an exact case, or `Rule/*` for a whole rule.
fn known_key<'a>(known: &'a BTreeMap<String, String>, case: &Case) -> Option<&'a String> {
    if let Some(reason) = known.get(&case.key) {
        return Some(reason);
    }
    let wildcard = format!("{}/*", case.rule);
    known.get(&wildcard)
}

fn known_differences(root: &Path) -> BTreeMap<String, String> {
    let mut known = BTreeMap::new();
    let Ok(text) = std::fs::read_to_string(root.join("known-differences.tsv")) else {
        return known;
    };
    for line in text.lines() {
        let line = line.trim_end();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (key, reason) = line.split_once('\t').unwrap_or((line, ""));
        known.insert(key.to_string(), reason.to_string());
    }
    known
}

fn implemented(registry: &RuleRegistry) -> BTreeMap<&'static str, &'static str> {
    let mut rules = BTreeMap::new();
    for descriptor in registry.descriptors() {
        rules.insert(descriptor.meta.name, descriptor.meta.codenarc_class);
    }
    rules
}

/// Upper bound on cases our parser cannot read yet, so parser regressions show up
/// here instead of quietly joining the known-differences list.
const PARSER_BUDGET: usize = 124;

#[test]
fn rules_match_codenarc_fixtures() {
    let root = corpus();
    let registry = RuleRegistry::builtin();
    let rules = implemented(&registry);
    let known = known_differences(&root);

    let mut passed = 0;
    let mut known_hits = 0;
    let mut parser_hits = 0;
    let mut unimplemented = 0;
    let mut failures: Vec<String> = Vec::new();
    let mut stale: Vec<String> = Vec::new();
    let mut matched_known: BTreeSet<String> = BTreeSet::new();

    for case in cases(&root) {
        let Some(class) = rules.get(case.rule.as_str()) else {
            unimplemented += 1;
            continue;
        };
        let path = root.join(&case.key);
        match run(&registry, class, &case, &path) {
            Ok(()) => {
                passed += 1;
                // An exact row that now passes is stale; a `Rule/*` row covers only
                // the cases that still fail, so it stays.
                if known.contains_key(&case.key) {
                    stale.push(case.key.clone());
                }
            }
            Err(message) => {
                let Some(_) = known_key(&known, &case) else {
                    failures.push(format!("{}: {message}", case.key));
                    continue;
                };
                known_hits += 1;
                let reason = known_key(&known, &case).expect("checked above");
                if reason.starts_with("ours-parser") {
                    parser_hits += 1;
                }
                if known.contains_key(&case.key) {
                    matched_known.insert(case.key.clone());
                } else {
                    matched_known.insert(format!("{}/*", case.rule));
                }
            }
        }
    }

    let mut unanswered: Vec<String> = Vec::new();
    for key in known.keys() {
        if !matched_known.contains(key) {
            unanswered.push(key.clone());
        }
    }

    // A green run should still say how much of the corpus is covered.
    println!(
        "codenarc fixtures: {passed} match, {known_hits} known differences ({parser_hits} blocked by \
our parser), {unimplemented} cases for rules we do not implement"
    );

    let report = format!(
        "{passed} pass, {} fail, {known_hits} known differences ({parser_hits} blocked by our parser), \
{unimplemented} cases for rules we do not implement\nfirst failures:\n{}",
        failures.len(),
        failures.join("\n"),
    );

    assert!(failures.is_empty(), "{report}");
    assert!(
        stale.is_empty(),
        "these known differences now match CodeNarc, delete the lines from known-differences.tsv: {stale:?}"
    );
    assert!(
        unanswered.is_empty(),
        "known-differences.tsv names cases that are not in the corpus: {unanswered:?}"
    );
    assert!(
        parser_hits <= PARSER_BUDGET,
        "known differences blocked by our parser grew from {PARSER_BUDGET} to {parser_hits}; \
         the parser got worse"
    );
}
